    "company_profile": "    大金重工股份有限公司(以下简称:大金重工)是新能源领域一家全球化运营的上市公司,致力于为客户提供有竞争力、安全可信赖的产品,同时提供行业相关服务运营等系统化解决方案,总部位于中国北京。公司主要产品为:海上风电/陆地风电全系列的塔架、转换段、基础段、大型管桩、深远海导管架、浮式基础、海上升压站等产品。作为一家全球多元化产业集团,公司在德国、波兰等欧洲国家和国内的辽宁、内蒙古、河北、山东、广东等省市拥有10余家成员企业,客户和销售网络遍及30多个国家和地区,在全球范围内拥有超过5000名优秀员工。大金重工于2000年创立于辽宁阜新,2010年在深交所主板上市,是国内风电塔筒行业的首家上市公司,经过20年的行业深耕,大金重工已经稳居全球风电装备制造产业先驱梯队,是国内出口欧洲海塔(14.7MW级)、亚洲出口欧洲超大型单桩(14.7MW级)的风电海工装备制造企业。此外公司在其他如新能源投资开发、风电产业园投资运营等产业链纵深的战略布局也在有序推进壮大,并快速成长为公司持续健康发展的新增长点。自创立之初,公司便确立了要在全球新能源领域打造大金的世界的产业理想,并始终保持着敏锐、专业的行业洞察力和判断力,得益于对工艺技术的不断升级创新和管理效率的不懈追求,大金保持了持续强劲的增长势头,逐步构建起公司全球战略的核心竞争力。随着中国及世界风电新能源产业政策的拐点,新能源装备制造产业成为了高景气度发展的细分行业。未来,公司将继续深度聚焦全球风电全产业链,致力于打造产业链的领跑者,构建大金的世界。为世界绿色低碳和地方经济发展振兴贡献力量。",
