    "website": "www.hengrui.com",
    "company_profile": "    江苏恒瑞医药股份有限公司(股票代码:600276.SH,01276.HK)创立于1970年,分别于2000年、2025年在上海证券交易所和香港联合交易所挂牌上市,成为“A+H”两地上市企业。作为一家专注研发、生产及推广高品质药物的创新型国际化制药企业,恒瑞医药在五十多年的发展历程中,始终坚持“以患者为中心”的初心,聚焦肿瘤、代谢和心血管疾病、免疫和呼吸系统疾病以及神经科学等领域,持续攻坚药物研发,为了攻克疾病、改善生活质量和延长生命,公司不断拓展可能的疆域,致力于运用科技的力量造福全球患者。恒瑞医药连续7年上榜美国《制药经理人》杂志公布的全球制药企业TOP50榜单;国际知名咨询机构Citeline发布全球TOP25管线规模制药公司榜单,恒瑞连续5年上榜,自研管线数量位居全球第二。用创新守护生命健康——恒瑞医药始终把科技创新作为第一发展战略,持续加码研发,公司研发投入占营业收入比重连续多年保持在25%以上,位居全国医药行业前列。研发投入催生丰硕创新成果,目前已有24款1类创新药和5款2类新药在中国获批上市,另有100多个自主创新产品正在临床开发,400余项临床试验在国内外开展,形成了上市一批、临床一批、开发一批的良性循环。研发平台方面,公司不断完善已建立成熟的ADC、双/多抗、蛋白降解剂、小核酸药物、口服多肽、PROTAC/分子胶/RIPTAC等技术平台,初步建成新分子模式平台。同时,恒瑞大力发展人工智能药物发现(AIDD),全面赋能药物研发的创新与迭代。努力推动中国制药品牌走向世界——稳步推进国际化,是恒瑞医药的长期发展战略。目前公司产品已进入50余个国家,还在继续加快开拓全球市场并重点关注新兴市场。公司坚持自主研发与开放合作并重,在内生发展的基础上着力加强国际合作。自2023年以来,公司已与MSD、GSK等知名跨国药企达成了12笔海外业务拓展交易,包括对外许可、NewCo和战略联盟等不同形式。同时,公司4款创新药获美国FDA快速通道资格认定,5款创新药获美国FDA孤儿药资格认定,并稳步推进多项欧洲及美国的注册申请。此外,公司已在海外获得包括注射剂、口服制剂和吸入性麻醉剂在内的约20个注册批件,提高了全球不同地区患者的药物可及性。未来恒瑞医药将始终坚持“科技为本,为人类创造健康生活”的使命,以“专注创新,打造跨国制药集团”为愿景,力争研制出更多的新药、好药,用科技创新服务人类健康。",
