    "company_profile": "    广东鼎泰高科技术股份有限公司成立于2013年,位于广东省东莞市厚街镇,是集研发、生产和销售为一体的国家高新技术企业。业务范围从PCB钻针、铣刀、刷磨轮、自动化设备、工业膜产品到数控刀具、表面涂层等,产品广泛应用于PCB、3C、汽车零配件、模具等行业。鼎泰高科被中国电子电路行业协会(CPCA,ChinaPrintedCircuitAssociation)连续多年评定为“优秀民族品牌企业”。PrismarkPartnersLLC(独立第三方顾问公司)的最新研究报告显示,2020年鼎泰高科的PCB钻针销量跃踞全球第一位,全球市场占有率19%,成为线路板行业微钻领域全球龙头供应商!鼎泰高科在技术研究方面,始终坚持“产学研用”的理念,秉承以企业为主体、以研发为核心、以市场为导向的原则,不仅与各大院校长期保持合作,还与业内多家知名企业建立了战略研发关系。为市场提供精良、稳定、高效的产品,公司进口了德国Walter和澳大利亚ANCA的全自动五轴工具磨床、德国ZOLLER全自动刀具检测仪、日本KEYENCE超景深数码显测量仪等全球先进设备,并成立了微钻、铣刀及精密刀具的产品研发测试中心。公司产品获得国内多家知名企业的认可,且远销欧美、韩国、东南亚等国家或地区。我们将持续创新、精益求精,以卓越的品质,超强竞争力的产品服务客户。",
