    "company_profile": "    广州广合科技股份有限公司(以下简称“公司”)于2002年在广州市黄埔区成立,2024年在深圳证券交易所主板挂牌上市,股票代码为:001389,股票简称为:广合科技。公司总部位于广州市黄埔开发区,生产基地主要分布在广东广州和湖北黄石。我们拥有高端的研发技术团队、优秀的管理团队以及国内外顶尖的自动化生产线。公司多年来一直致力于打造成为集高端优质PCB产品的研发、生产、销售、服务为一体的行业领先电路板制造企业。广合科技一直致力于以高速、高频为主的高端PCB制造,产品主要应用于数据中心、云计算、工业互联网、人工智能、5G通讯、汽车电子、安防和打印等终端领域。广合科技长期服务于国内外知名客户。多年来,公司规模和技术能力在PCB领域保持持续快速成长,并连续多年被公司主要客户评定为优秀供应商和长期战略合作伙伴。我们注重公司品牌价值、产品研发、产品品质、营销策略、企业文化的打造,通过先进的前沿技术,制造出优质的产品,打造便捷的产品渠道,提供贴心、快捷的售后服务,独创具有特色的运营管理模式,以“服务客户”为宗旨,为推进“智能制造”同步发展的新业态结构建设提供创新动力和重要支持,我们立誓成为国内外PCB产业发展的领航者。在用人方面,公司始终坚持以德为本、德才兼备、不拘一格、能者居上的用人原则,致力于发掘和培养人才,并为其提供可持续发展的机会和丰厚的薪酬福利,达成公司、客户、职工三赢。在此我们诚邀各路精英加盟,并衷心希望您的才能在这里得到充分的发挥,让我们携起手来共创辉煌!",
