    "website": "www.shpcb.com",
    "company_profile": "    胜宏科技(惠州)股份有限公司于2006年7月落户广东省惠州市惠阳区淡水街道行诚科技园,在职员工1万人(全球约1.6万人)。2015年6月在深交所创业板上市,股票代码:300476。公司是全球领先的人工智能及高性能计算PCB供应商,专注于高阶HDI、高多层PCB的研发、生产和销售,产品广泛应用于人工智能、新能源汽车、高速网络通信等高增长领域。凭借前瞻性的战略布局及卓越的技术转化能力,不断突破PCB前沿技术、打造了多元化产品组合,构建了覆盖单层及双层PCB、高多层PCB、高阶HDI及FPC的全品类产品组合,服务超过350家需求庞大的全球客户。公司是CPCA副理事长单位,行业标准的制定单位之一,拥有省级工程技术研发中心和省级企业技术中心,拥有线路板领域有效专利,连续四年获“中国专利优秀奖”。先后通过ISO9001、QC080000、IATF16949、UL2799及ISO27001等多项体系认证,获评“国家高新技术企业”、“国家知识产权优势企业”、“国家级绿色工厂”、“广东省创新型企业”、“优秀民族品牌企业”等荣誉称号。公司通过实施智慧工厂、绿色制造、高技术/高品质/高质量服务的“三大战略”,推进观念、科技、人才和资本“四个创新”,成功打造同行业中国第一家新一代工业互联网智慧工厂。公司积极参与客户产品预研,深化与全球头部科技行业客户战略合作。凭借战略优势、技术优势和品质优势,已成为众多海外及中国头部科技企业的核心合作伙伴,在AI算力、AI机器人、无人驾驶、虚拟现实等领域取得领先优势,在行业内树立了标杆地位。",
