    "company_profile": "    迈威(上海)生物科技股份有限公司(688062.SH)是一家全产业链布局的创新型生物制药公司,始终秉承“让创新从梦想变成现实”的愿景,践行“探索生命,惠及健康”的使命,通过源头创新,为患者提供疗效更好、可及性更强的生物创新药,满足全球未被满足的临床需求。迈威生物构建了以抗体药物靶点发现与分子发现为起点,覆盖成药性研究、临床前研究、临床研究和生产转化等药品研发全周期的创新体系,实现集研发、生产、营销于一体的全产业链布局。我们专注于肿瘤和年龄相关疾病,涉及肿瘤、自身免疫、骨疾病、眼科、血液、心血管等治疗领域,凭借国际领先的特色技术平台和研发创新能力,建立了丰富且具有竞争力的管线。并独立承担1项国家“重大新药创制”重大科技专项、2项国家重点研发计划和多个省市级科技创新项目。迈威生物以创新为本,注重产业转化,符合中国NMPA、美国FDA、欧盟EMA GMP标准的抗体和重组蛋白药物产业化基地已在江苏泰州投入使用,并已通过欧盟QP审计,位于上海金山和江苏泰州的大规模商业化生产基地正在建设中。",
