    "company_profile": "    广州银诺医药集团股份有限公司成立于2014年,是一家科学驱动的生物制药公司,致力于为代谢性疾病患者提供创新的,可及且可负担的高质量药品。公司目前已拥有多项针对糖尿病、肥胖,代谢功能障碍相关适应症的研发管线,且所有管线均为自主研发,拥有全球专利,并布局全球研发和市场销售。  公司首个管线产品依苏帕格鲁肽α(曾用名:苏帕鲁肽,商品名:怡诺轻)于2025年1月份获中国国家药品监督管理局批准上市,成为本国首个国产原研的人源化长效GLP-1受体激动剂产品,将惠及更多的糖尿病患者。公司同时在开发依苏帕格鲁肽α减肥和代谢功能障碍相关的脂肪性肝炎适应症,以满足这些疾病领域巨大的未满足治疗需求。  银诺研发团队由国家特聘专家领衔,与具有多年创新药研发经验的科学家队伍组成,其创始人,董事长兼首席执行官,依苏帕格鲁肽α发明人王庆华博士是复旦大学特聘专家,十三五国家科技“重大新药创制”项目课题负责人。王庆华教授曾是多伦多大学的终身教授及世界领先的班廷百思特糖尿病研究所的常务委员。  银诺医药拥有先进的重组蛋白生物药技术平台可用于创新生物药的持续研发。",
