    "employees": "1998",
    "website": "www.bayzedhealthcare.com",
    "company_profile": "    佰泽医疗集团致力于打造中国领先的肿瘤全周期医疗集团,经营6家自有民营营利性医院,管理及运营2家民营非营利性医院,分布于北京、天津、安徽、山西、河南等地,专注于提供肿瘤“防-筛-诊-治-康”全周期、全链条的医疗服务,并为旗下医院提供优质的医疗资源、管理经验,对其进行精细化运营管理。作为肿瘤全周期医疗的倡导者和引领者,集团制定了明确的战略方向,围绕肿瘤全周期展开核心业务,涵盖肿瘤的预防、早癌筛查、诊断、治疗和康复各个阶段,拥有国内外顶尖肿瘤专科医疗资源,整合医教研多方资源,以创新的技术手段和丰富的医疗资源,为患者提供精准化、个性化、综合性的治疗方案,助力患者实现早期发现、早期治疗和全程康复,为更多的肿瘤患者带来希望和健康。佰泽医疗集团始终坚持以学科建设为引擎,打造核心竞争力,着力提高肿瘤全周期医疗服务的准确性、安全性和便捷性。集团未来将进一步扩大医院网络,通过制定学科建设科学发展规划,建设临床重点专科群,以学科建设带动诊疗能力和水平提升,并提升综合竞争力。在推动医学领域创新及研究能力方面,集团与北京大学肿瘤医院、石学敏中医发展基金会、北大医学科创中心等机构紧密合作,注重科研与创新,引进国际领先的医疗技术和设备,加强与国内外医学研究机构的合作,不断深化医学研究,推动肿瘤领域前沿成果转化,为肿瘤患者提供更加前沿、个性化的肿瘤治疗解决方案患者更加精准、有效的医疗服务。集团坚持“以患者为中心”的服务精神,注重医疗资源的整合和运营管理,拥有一支富有经验和专业知识的管理团队,为患者提供高质量的医疗资源和优质服务,通过运用现代化的管理理念和技术手段,他们不断优化医疗流程和管理效率,为患者提供更优质的医疗体验。同时,集团积极践行社会责任,通过开展公益活动、科普下基层、医疗合作,为更多地患者提供医疗帮助,获得当地患者的好评和认可。通过这些年的发展和努力,集团及旗下医院获得业内认可,2023年10月,佰泽医疗集团荣登2023届艾力彼社会办医·医院集团100强榜单,旗下太原和平医院荣登2023届社会办医·康复医院榜单全国第4名,北京京西肿瘤医院荣登2023届社会办医·肿瘤医院榜单全国第12名,黄山首康医院荣登2023届社会办医·单体医院300强榜单,北京京西肿瘤医院、太原和平医院、武陟济民医院、天津石氏医院荣登2023届社会办医·单体医院500强榜单。",
