    "company_profile": "    手回集团有限公司是一家中国人身险中介服务提供商,致力于通过数字化人身险交易及服务平台,在线为保险客户提供保险服务解决方案。公司分销的保险产品(包括与保险公司共同开发的保险产品)由保险公司承保,公司不承担任何承保风险。根据弗若斯特沙利文的资料,于2023年,按总保费计,中国的人身险市场规模为人民币3.8万亿元。公司主要与保险中介机构和保险公司内部销售人员竞争。此外,公司亦与其他市场参与者(包括银行保险渠道及保险兼业代理机构)竞争。根据弗若斯特沙利文的资料,于2023年,中国人身险中介市场的总保费达至人民币2,370亿元,占中国人身险市场总保费的6.3%。于2023年,以中国人身险中介市场的总保费计,公司排名第八,市场份额为2.9%。线上中介在中国人身险中介市场中占据主导地位,并于2023年占中国人身险中介市场总保费的89.1%。根据弗若斯特沙利文的资料,以2023年的长期人身险的总保费计,公司是中国第二大线上保险中介机构,占据7.3%的市场份额,仅次于市场上的一家主要参与者,份额为45.5%。以2023年的长期人身险的首年保费计,公司是中国第二大线上保险中介机构。",
