    "company_profile": "    山东天岳先进科技股份有限公司成立于2010年11月,是一家专注于碳化硅单晶衬底材料研发、生产和销售的科技型企业。公司秉承“先进·品质·持续”的经营理念,以满足客户需求、帮助客户解决问题为导向,重视产品品质和服务品质,自主掌握工艺技术,积极拓展市场,追求业务可持续发展。碳化硅单晶衬底材料是一种宽禁带半导体材料,和传统材料相比具有更加优异的物理性能,可以有效提升下游器件的功率密度和整体性能,在电力电子以及微波电子领域有着广泛的应用前景。但优越的物理性能背后是精密且复杂的制备工艺,碳化硅单晶的生长需要在高温低压密闭环境下进行,且微小的环境变化都会引起晶格错乱从而影响衬底材料的品质。公司依托卓越的研发团队和多年积累的产业化经验,重视技术引领、品质提升,长期坚持创新,以打造一体化解决方案为核心,完善服务、完善产品,力争成为国际著名的半导体公司。",
