    "website": "www.anjoyfood.com",
    "company_profile": "    安井食品集团股份有限公司成立于2001年12月,公司主营速冻调制食品、速冻面米制品和速冻菜肴制品等速冻食品的研发、生产和销售。经过二十多年的发展,公司逐步成长为国内最具影响力和知名度的速冻食品企业之一。公司已在国内布局安井食品集团厦门总部、无锡安井、泰州安井、辽宁安井、四川安井、湖北安井、河南安井、广东安井、山东安井、新宏业、新柳伍及洪湖安井,共计12大产销研一体化生产基地,另有无锡营销、安井冻品先生、湖北安润及英国功夫食品(ORIENTAL FOOD EXPRESS LIMITED)等控股或参股子公司。公司形成了以华东地区为中心辐射全国的营销网络,营销驻外机构合计54个,包含10个分公司、31个联络处、13个独立工作站。目前,公司拥有一级经销商,主要商超客户包括大润发、永辉、沃尔玛、物美、天虹等连锁大卖场,并与包括张亮麻辣烫、半天妖烤鱼、呷哺呷哺、海底捞、鱼你在一起酸菜鱼等国内多家餐饮连锁客户,以及湖北旭乐、浙江瑞松等休闲食品类上市公司上游供应链企业建立了长期合作关系。为满足消费者日益多元化的需求,近年来公司打造了锁鲜装系列、火山石烤肠、虾滑、烧麦、小龙虾、小酥肉、牛羊肉卷等明星产品,深受市场欢迎。公司坚持“BC兼顾、全渠发力”的渠道策略,在夯实传统流通、商超渠道的基础上,不断加深特通、新零售和兴趣电商等全渠道开发,通过合理渠道组合实现效益最大化。公司荣获由国家发改委、国家科技部等五部委联合认定的速冻调制食品行业首家“国家级企业技术中心”;农业农村部颁发的“农业产业化国家重点龙头企业”“全国主食加工业示范企业”以及“国家冷冻调理水产品加工技术研发专业中心”“国家鱼糜及鱼糜制品加工技术研发中心联合单位”等称号;中国合格评定国家认可委员会颁发的“CNAS国家实验室证书”以及“全国工业品牌培育示范企业”“出入境检验检疫信用管理AA级企业”“福建省海洋产业龙头企业”等多项殊荣。公司主持或参与《速冻食品术语》《冷冻鱼糜》等100余项标准的制修定工作,其中63项已完成并发布。2017年2月22日,公司在上海证券交易所主板挂牌上市,股票简称“安井食品”,股票代码“603345”。继2022年成为国内速冻食品行业首家年营收超过百亿、利润过十亿的集团公司之后,2023年度,公司实现了显著的利润增长,继续巩固了速冻食品行业的龙头地位,展现了强大的发展韧性,稳居国内速冻食品行业规模第一、利润第一和市值第一。安井始终秉承“食以民为天”的经营宗旨,“让美味更安心”的企业使命,“责任、正道、行动、共赢”的企业价值观和“马上去做、用心去做”的企业作风,坚持在产品力、渠道力和品牌力上深挖潜力,致力于为消费者提供更好更优质的产品,提高品牌美誉度和企业竞争力,以企业可持续高质量发展服务健康中国建设。",
