    "company_profile": "    白鸽在线(厦门)数字科技股份有限公司是中国领先的数智化风险管理企业,获国家高新技术企业、金融科技创新监管工具创新应用企业、专精特新企业、科技小巨人及独角兽企业认定,引进新希望集团、国投智能、通联支付、民银资本等作为战略股东。作为人工智能垂直模型领域的头部企业,白鸽在线通过“AI+金融+场景”大数据,提供场景化保障方案,全流程数字化应用以及AI应用服务,依托自主研发的MaaS平台,以智能风控引擎、动态定价模型等为核心,持续为金融行业输出决策模型,并为城市建设提供智能风控治理平台,实现从风险预防、评估到保障的全流程风控管理。目前,白鸽在线已将AI技术嵌入超过百类场景,构建出行、灵活用工、车服、物流、大健康等“9+N”生态体系,累计服务用户数近4亿,生成数字保单超90亿单。",
