    "latest_price_date": "2026-07-13",
    "chairman": "张矿",
    "employees": "350",
    "website": "www.grkaolin.com",
    "company_profile": "    安徽金岩高岭土新材料股份有限公司,成立于2012年10月25日,坐落于安徽省淮北市美丽的朔西湖畔。公司专业从事煤系高岭土采选、研发、加工、生产和销售,是国内一家品种较全、大规模、正规化井下开采的煤系高岭土深加工生产企业。2025年1月,公司新建一条30万吨精铸用莫来石生产线及一条20万吨晶相转化生产线开始商业生产。公司系国家高新技术企业、国企改革\"科改示范企业\"、国家级专精特新\"小巨人\"企业、安徽省制造业单项冠军培育入库企业。公司于2022年11月成功在新三板挂牌,证券代码:872844;2025年12月3日,在香港联合交易所主板成功挂牌上市,证券简称:金岩高岭新材,股份代号:02693.HK。金岩高新凭借其全价值链的整合能力,从采矿、研发、加工到生产、销售,展现了强大的市场竞争力。公司依托丰富且优质的煤系高岭土矿产资源,专注于生产精铸用莫来石材料和耐火用莫来石材料,这些产品在精铸型壳和耐火材料领域具有重要应用。此外,公司还提供生焦生粉,供客户进一步加工使用。通过垂直整合的业务模式和卓越的产品质量,金岩高新在市场中确立了稳固的地位。根据弗若斯特沙利文提供的2024年数据,我们是中国精铸用莫来石材料制造商第1名,市场占有率为19.1%。公司先后获得\"安徽工业精品\"\"安徽省商标品牌示范企业\"\"安徽省工业和信息化领域标准化示范企业\"\"皖美品牌示范企业\"等多项殊荣,在行业发展的征程中留下了坚实而璀璨的足迹。金岩高新始终把科技创新作为引领新质生产力发展的主攻方向,建立了ERP系统、智能仓储管理系统等,与多家高等院校和研究机构建立产学研一体化合作,在技术、曾理、研发上多维度创新,推动高岭十加工行业向现代化、智能化、绿色化的新业态、新模式转型升级,为行业可持续发展提供了有益借鉴。公司莫来石基铝硅系材料深加工项目,目前正处于实施阶段,该项目由7万吨/年莫来石级配料生产线和6万吨/年高岭岩精细粉生产线组成,项目建成后将加快硅酸铝质系列耐火材料、高岭岩精细粉,向高端化、优质化、高性能方向升级。金岩高新时刻关注着行业发展,在煤系高岭土的开发、深加工及产品标准化等方面一直走在行业的前沿,牵头推出高岭土和莫来石材料的行业标准,如《熔模铸造用煅烧高岭土砂、粉》(T/CFA0202044-2021)、《熔模铸造用煅烧高岭土砂粉》(JB/T11733-2013)和《焦宝石化学分析方法》(JC/T2782-2023),具备强大的创新实力和技术储备。金岩高新将坚持以\"点石成金,勇攀峻岩\"为事业追求的至高境界,用持之以恒的匠心精神,实现对产品的精益求精。按照产业发展规划,金岩高新将深挖自身得天独厚的资源优势,精准定位发展方向,积极拓展耐火材料和陶瓷纤维市场,实现高岭土资源的高质量、多元化利用,通过不断创新与突破,全力塑造行业一流、全国领先的煤系高岭土新材料标杆企业,为产业升级贡献金岩力量。",
