    "company_profile": "    南京埃斯顿自动化股份有限公司(深交所上市,股票代码:002747)成立于1993年,始终秉承\"开放、创新、奋斗、共成长\"的发展理念,坚持走自主研发核心技术之路,立足中国,整合全球人才资源,为全球客户提供高品质的产品和智能化完整解决方案,推动中国智能制造享誉全球。公司坚持\"ALL Made By Estun\"全产业链战略,构建了完全自主可控的智能制造生态链。埃斯顿连续七年稳居中国工业机器人国产品牌出货量首位,2025年上半年以10.5%的市场占有率登顶中国机器人销量总榜榜首(MIR数据)。埃斯顿深入洞察市场需求,结合创新技术,成功培育三大核心业务:(1)工业自动化系列产品。埃斯顿拥有自主化运动控制核心技术,打造TRIO/埃斯顿双品牌,产品包括:HMI、数控系统、运动控制器、PLC、交流伺服系统(50W-200KW)、编码器等丰富的自动化核心部件系列产品,覆盖信息层-控制层-驱动层-执行层,为电子制造、半导体、锂电池、包装、纺织、机床等行业构建了TRIO+ESTUN智能控制完整解决方案。(2)工业机器人及智能制造解决方案。基于自主化机器人核心技术,埃斯顿打造了95款工业机器人产品,覆盖3kg-1200kg负载,产品包括SCARA机器人、协作机器人、通用多关节机器人、行业专用机器人(高防护、洁净、防爆、折弯、码垛、焊接、冲压等)。拥有数十种成熟的行业工艺软件包,广泛应用于汽车、光伏、锂电池、汽车零部件、电子制造、工程机械、海工船舶等各个领域,为行业头部品牌打造灯塔工厂。(3)数字化产品及数字化服务。产品包括工业软件及数字化平台,覆盖产线设计与验证--集成交付--运维服务的全生命周期解决方案,打造了E-Noesis云平台、远程运维平台E-Care,提供涵盖过程质量检测与优化、故障预警分析、远程运维、数据融合等数字化功能,使设备参数、工艺参数、产能、质量数据透明化,为用户打造数字化核心竞争力。持续聚焦创新技术,埃斯顿打造免示教焊接、免示教打磨、视觉引导无序抓取等解决方案,将运动控制、机器视觉、AI编程等多种跨领域技术进行融合,实现了免示教、部署方便、易用性提升。基于埃斯顿新一代NGC控制平台,我们为用户提供更为二次开放更强的ERI实施操控平台,融合了多种API、开发套件和SDK接口,同时提供实时交互通道(支持4ms通讯速率),为多机器人协同,机器人+外部轴/多维传感器等领域提供完整解决方案。埃斯顿积极布局全球产业链,与英国TRIO、德国CLOOS、德国M.A.i等全球知名制造商携手打造增长型合作生态,实现全球化服务与支持。业务覆盖中国、欧洲、东南亚、美洲,产品拥有符合国际标准的CE、UL等安全认证。同时,埃斯顿以南京为研发中心,整合德国、英国、美国等全球研发资源,组建了一支具备国际领先能力的研发团队,为全球客户提供数字化完整解决方案。埃斯顿始终以\"人人享受自动化\"为企业使命,让制造更智能、让品质更卓越、让生活更美好、让世界更绿色!For a better life!",
