    "company_profile": "    青岛国恩科技股份有限公司,成立于2000年12月22日,座落于青岛市城阳区青大工业园,中国A股上市公司(股票简称:国恩股份,股票代码:002768.SZ),国家首批高新技术企业。公司以国恩系纵向一体化产业平台为中枢,以长期规模效益为目标,以大化工及大健康产业为两翼,实施“一体两翼”发展战略,协同上下游产业链的研发、生产、服务、应用为一体,全面推动各板块业务的快速发展。公司持续优化产业结构,已初步发展成为拥有绿色石化、有机高分子改性、有机高分子复合、人造草坪、可降解、光显、熔喷过滤,以及新能源汽车轻量化结构部品等化工新材料纵向一体化产业集群。同时,控股胶原领域上市公司东宝物(股票代码:300239),产品拥有明胶、空心胶囊、胶原蛋白、代血浆明胶、双蛋白膳食纤维、医美产品,形成以医、美、健、食为主体的大健康产业细分领域的综合性企业集团,拥有浙江一塑、江苏国恒、日照国恩化学、国恩塑业、国恩复材、国骐光电、国恩体育草坪、广东国恩、东宝生物、益青生物等二十余家子公司。近年来,公司通过延伸产业链,打通供应链,提升价值链,构建生态链,不断整合市场资源,通过发挥大化工、大健康产业纵向一体化平台的资源开发优势,积极为客户提供多品类的产品和优质的服务,不断打造点阵式产业集群生产基地,通过“新材料+”推进大化工产业精准布局、“胶原+”赋能大健康产业多维发展的战略发展模式,持续强化公司综合实力。国恩股份始终践行“以至诚之心,献至诚之作”的宗旨,秉承“塑世纪国恩,兴百年科技”的经营理念,充分发挥产业规模化优势,释放上市公司资本聚合效应,全面聚焦核心战略落地,不断通过延伸上下游产业链,拓展多元化业务方向,形成产业纵向协同、横向联动、全面发展新局面,用科技创新引领公司在大化工和大健康领域高质量发展的新征程!",
