    "website": "www.hanscnc.com",
    "company_profile": "    深圳市大族数控科技股份有限公司成立于2002年(股票代码:301200.SZ,3200.HK)是集PCB专用设备技术研发、生产与销售于一体的国家级高新技术企业,聚焦人工智能、汽车电子、消费电子、通信设备等电子终端印制电路板(PCB)领域,为全球客户提供PCB各细分市场及应用场景的创新型生产解决方案。大族数控是全球PCB专用生产设备领域工序解决方案布局最为广泛的企业之一;覆盖常规刚性多层板、高密度互联板(HDI)、类载板(SLP)、载板(ICSubstrate)、挠性及刚挠结合板(FPC&Flex-Rigid)等所有细分PCB产品的钻孔、曝光(内层、外层、阻焊)、成型、电性能检测、贴补强及自动化等关键工序,提供包括机械钻孔机、CO2/UV/超快激光钻孔机的钻孔方案,LDI激光直接成像方案,机械成型、激光成型方案,专用/通用/高精测试方案,钢片补强机及辅材贴附等多系列多种类工序解决方案。随着数字化时代的来临,我们大族数控将全力以赴,共同努力,持续提升设备的技术水平,提高国产PCB专用设备的全球产业竞争力,树立民族PCB高端设备的品牌形象,迎接我国PCB行业工业4.0大规模自动化/智慧化生产的到来,为PCB产业的智慧化生产及智慧工厂奉献力量。大族数控的经营理念是精于质量、诚于服务。公司于2006年取得ISO-9001质量认证,对产品质量精益求精,采用先进和高精度的检测设备,生产中每一个零件都经过严格的质量检验,整机更是采用极限速度核对总和超长时间工作检验的方式,确保出货设备的高精度、高稳定性、高可靠性。大族数控的庞大技术支援和售后服务网络提供强大的技术支援和良好的客户增值服务。大族数控拥有超大装配车间,车间宽大,明亮,整洁,有序;拥有各类设备的固定生产线;具有年产数千台PCB专用加工设备的强大供应能力,并在核心零部件供应商的管理和开发、备品库存管理、生产制造和质量控制、人员调度等供应链体系的多方面表现优越,拥有全球范围内领先的交付能力,可快速满足PCB产业对专用设备的需求。大族数控一直提倡团队精神,重视人才,大胆应用新材料、新技术、新工艺。公司拥有一批学历层次高,经验丰富的高级专业技术队伍和稳定的专家顾问群,科研人员占公司人数的30%,开发人员绝大部分具有大学本科以上学历。专业领域涉及机械、材料、光学、电子、自动控制、运动控制、电子信息工程、软件、机器视觉等。研究人员中既有长期从事机械设计、自动控制、激光技术研究的学术造诣高的专家,也有新兴技术,数字影像处理,计算机软件技术等方面具有丰富实践经验的中青年学者,同时还有丰富实践经验的工程师和工程技术人员,形成一支年龄结构合理,既有先进技术,又有丰富工程实践经验的科技开发队伍。公司与国内著名高校长期合作,建立产学研和人才定向培养平台,确保公司技术的持续领先性。",
