    "chairman": "袁荣",
    "employees": "1092",
    "website": "www.jinxunec.com",
    "company_profile": "    云南金浔资源股份有限公司成立于2010年1月,位于云南省昆明市高新区昌源北路1389号航空航天大厦B座3层。公司于2017年2月挂牌新三板,并入选创新层(证券代码:870844)。立足于有色金属行业的理解和深耕,践行国家“一带一路”战略,致力于成为集有色金属新能源材料洗选、冶炼、深加工的有色金属新能源新材料产业链开发运营商。公司始终以国家“一带一路”倡议为指引,以“走出去”战略为导向,积极开拓海外市场,已形成依托非洲优质矿产资源的生产产业链、国内国外双循环的发展架构。2016年8月,公司在非洲赞比亚设立了控股子公司荣兴投资有限公司(以下简称“荣兴投资”),荣兴投资是金浔股份践行“走出去”的成功案例;荣兴投资已建成年产6,000吨阴极铜的湿法冶炼厂,实现公司在有色金属矿产加工领域的突破。2018年8月,公司成立全资控股公司金浔刚果(金)矿业有限责任公司(以下简称“金浔刚果金”),积极开拓非洲刚果金市场。2022年3月,金浔刚果金在当地投资建设年产10,000吨阴极铜和3,000吨粗制氢氧化钴的湿法冶炼厂项目。2020年10月,公司成立全资控股公司金浔秘鲁矿业有限公司,进一步扩大了金浔股份“一带一路”朋友圈,为公司开拓美洲市场奠定了坚实基础。金浔股份依托海外丰富的资源优势,更好地实现公司“资源报国”的伟大梦想。为布局产业链上下游延伸,2022年10月,金浔股份设立安徽金浔新能源材料有限公司,国内年产50,000t/a高性能锂离子动力电池原材料项目落地安徽省合肥市庐江县工业园区,一期4,000金属吨钴盐项目建设正在紧锣密鼓推进中;未来随着安徽金浔的建成投产,金浔股份将实现由传统的制造业延伸向新能源材料业发展。习近平总书记说过:“无论相隔多远,只要我们勇敢迈出第一步,坚持相向而行,就能走出一条相遇相知、共同发展之路,走向幸福安宁和谐美好的远方。”作为“一带一路”的先行者,金浔股份将以行业“时代领跑者”为追求,将个人的梦想融入公司、国家、民族的梦想,将个人的发展与国家的富强、民族的复兴结合起来,企业和员工将携手共进,与时代同频,与国家一起努力奔跑,以奋斗者姿态做新时代的追梦人。金浔股份实施创新驱动发展战略,每年持续投入科研,利用现有的浮选和湿法生产技术,已授权二十四项专利。同时,金浔股份于2016年9月取得六项商标注册证书,对维护企业品牌,扩大企业影响,都将具有积极的意义,标志着公司在品牌建设方面取得了一个里程碑的胜利。2022年1月,金浔股份正式获得质量、环境、职业健康安全管理体系认证证书,意味着公司在质量管理、环境管理和职业健康安全管理方面迈上一个新台阶,在管理创新过程中取得新成果!近年来,在各级政府和领导的关心和支持下,金浔股份取得了一些荣誉,包括:中国有色金属协会企业信用等级AAA级、云南省专精特新中小企业、云南省“金种子”企业、云南省优强民营企业、昆明市高新区先进基层党组织、云南省劳动关系和谐企业等。未来金浔股份将继续在党和政府的领导下,充分展现云南省民营企业“走出去”的特色,将“资源报国、产业报国”做到实处,为云南省经济发展、中非友谊维护做出更多的贡献!",
