    "company_profile": "    圣邦微电子(北京)股份有限公司是由资深半导体设计工程师发起建立的,公司的目标是成长为一家领先的综合性模拟集成电路公司。公司从一开始就确立了以客户需求为中心、以创新迭代方式开发和生产高度可靠性、高度一致性模拟集成电路产品的经营原则,是一家工程师文化主导的公司。公司从建立初期就瞄准各类工业应用作为核心客户群,从运算放大器和LDO开始逐步将产品线宽度扩展到了完整的模拟信号、混合信号调理链路和完整的系统电源管理产品线。公司从第一个产品开始,就选择台积电为晶圆代工合作伙伴,实现了CMOS工艺在高精度、低噪声、高速系列运算放大器产品对传统双极工艺产品的快速替代,建立了相对传统工艺的成本优势。公司始终坚持独立自主的产品开发原则,追求对所有产品设计的深度理解和持续迭代能力,积累了自身专有的产品知识产权体系,逐步建立起了系统质量控制机制。公司注重细节,追求持续改进,力图为客户提供最方便的支持和最省心的服务。公司成立至今,保持了创始团队的稳定和业务的持续稳定发展。公司自2009年起一直保持了公司年度经营结果的持续盈利,2017年6月6日公司在深圳证券交易所开始公开上市交易(交易代码300661)。公司提供的所有产品都是绿色产品,符合行业低卤标准;在为客户提供较短交期的交货服务和大规模高质量产品方面持续保持着优良的客户口碑。公司以成为全球领先的综合模拟集成电路提供商为目标,在持续发展工业客户业务的同时,对全球最具活力的通信信息相关消费类电子产品领域应用保持了强大的适应能力,锻炼了公司稳定的供应链管理能力和成本竞争能力。公司在工厂自动化、光伏逆变系统、新能源汽车、锂电池化成设备、白色家电、5G移动通信基站系统、光纤通信收发器模块、服务器、自动化办公设备、机器视觉、智能手机、音响系统、虚拟现实、游戏机、智能手表等领域与世界范围内领先的品牌厂家建立了直接合作关系。",
