    "board": "非H股",
    "listing_date": "2025-12-30 00:00:00",
    "issue_price": 24.05,
    "issue_num": 108894000.0,
    "trade_unit": 500,
    "currency": "0.0000005 USD",
    "total_ipo_size_mn": 293.0,
    "cs_size_mn": 115.0,
    "cs_ratio": "39.2%",
    "first_day_close": 29.98,
    "first_day_change_pct": 24.66,
    "six_month_close": 41.38,
    "change_6m_pct": 72.06,
    "last_close": 44.94,
    "latest_price_date": "2026-07-13",
    "chairman": "Aleksandrs Zavoronkovs",
    "employees": "317",
    "website": "insilico.com",
    "company_profile": "    英矽智能成立于2014年,为一家信誉卓着、业务遍布全球的AI驱动药物发现及开发公司。截至最后实际可行日期,公司已透过自主开发的生成式人工智能平台Pharma.AI产生逾20项临床或IND申报阶段的资产,其中三项资产已授权予国际制药及医疗保健公司,最高合约总价值20亿美元,包括总额约110.0百万美元的预付款项以及约19亿美元的里程碑付款,以及一项处于自主开发阶段的II期资产,在业界中处于相对较为先进的阶段。公司采用项目制业务模式运营,主要收入来源为对外授权及合作安排,惟无法保证或明确预测未来收入产生情况。在公司的药物发现与管线开发业务中,公司(i)自主开发候选药物;(ii)共同开发授权药物并保留部分知识产权;及(iii)与其他制药公司合作但不保留任何知识产权。利用Pharma.AI,平均而言,公司的候选药物从靶点发现到临床前候选药物(PCC)确认需时12至18个月,远短于传统方法(平均需时4.5年)。PCC指一个分子已完成靶点验证、苗头化合物识别、先导化合物生成及先导化合物优化的时间点,并基于对效力、选择性、药代动力学、安全系数及可开发性的全面评估,被选为优化的候选药物以推进IND促成研究。由于PCC是一个行业标准里程碑,其涵盖了直接受公司AI驱动的设计流程影响的整个发现及优化阶段,因此达到PCC所需的时间是衡量发现效率的广泛接受的基准。公司独特的双引擎业务模式结合了生成式AI平台与深厚的自主药物研发能力,实现了持续的强化学习,不断提升Pharma.AI的能力并推动科学创新。公司亦正将Pharma.AI的应用范围扩展至多个行业,如先进材料、农业、营养产品及兽医药物领域。",
