    "company_profile": "    佳鑫国际资源投资有限公司(以下简称“佳鑫国际”)于2014年8月在香港注册登记成立(注册证书:2138962),佳鑫国际由四个股东组成,即香港恒兆国际有限公司、江西铜业股份有限公司、中国铁建国际投资集团有限公司、中国土木工程集团有限公司。佳鑫国际属下哈萨克斯坦杰特苏钨业有限责任公司巴库塔钨矿项目是中国及哈萨克斯坦两国政府产能合作45个重点项目之一。公司是紮根於哈萨克斯坦的钨矿公司,专注於开发公司的巴库塔钨矿(「巴库塔钨矿项目」),根据弗若斯特沙利文的资料,截至2024年12月31日,那是一个全球最大型三氧化钨(WO3)矿产资源量露天钨矿。根据弗若斯特沙利文的资料,截至2024年12月31日,公司的巴库塔钨矿亦是全球第四大WO3矿产资源量钨矿(包括露天钨矿及地下钨矿),在单一钨矿中拥有世界上最大的设计钨矿产能。於往绩记录期,公司主要专注於为巴库塔钨矿项目的商业生产作准备。巴库塔钨矿项目於2025年4月开始一期商业生产,2025年的目标年度采矿及矿物加工能力为3.3百万吨钨矿石。2024年第四季度将巴库塔钨矿项目投入试生产,截至2023年12月31日,公司已完成预剥采及主要建设工作,且於2024年下半年完成加工厂设备的安装及尾矿设施(TSF)一期堤防建设。公司已於2025年4月就巴库塔钨矿项目展开一期商业生产。公司预期於2026年完成整合矿石分选系统至现有采矿流程,并於2027年第一季度就巴库塔钨矿项目展开二期商业生产。",
