    "company_profile": "    深圳市星源材质科技股份有限公司成立于2003年的深圳星源材质,以开拓创新的精神,变革担当的魄力。以“星源膜创造新生活”为使命专注于新能源、新材料领域,成为了全球锂电池隔膜行业领跑者。2016年,星源材质在深交所挂牌上市奠定了公司产能扩张和国际化发展的基石。经过近二十年的发展,星源材质形成了以深圳总部为中心,以深圳、合肥、常州(两地)、南通、欧洲瑞典、佛山、东盟和美国九大生产基地为依托,深圳(隔膜技术、前沿技术及装备研究)、华东(南通)、日本大阪及欧洲瑞典六大研究中心并存的全球战略布局。产品涵盖锂电池干法、湿法、涂覆隔膜,成为了全球行业产品种类最多、质量最优的锂电池隔膜企业。凭借锂电池隔膜强大的技术优势,星源材质实现了锂电隔膜的国产化,彻底打破国外技术封锁,并开启了我国锂电隔膜的国产化道路,成为国内最早批量出口海外市场的隔膜企业。公司产品主要应用于新能源汽车、消费电子及储能电站等领域,并成功在航天航空领域取得应用,为我国产业安全作出了重要贡献。从2013年开始,产品批量出口LG化学等海外市场,实现了国内锂电池隔膜出口零的突破。作为企业保持着强劲发展的动力源泉,星源材质拥有国际一流的科研团队,研发技术类人才占比超过20%,并与国内外知名科研院校、机构长期保持紧密合作关系。星源材质拥有行业领先的智能化设备、研发中心和现代化生产基地,实现研、产、销一体化,形成了集约化、高效化、强大的产品供应链体系。根据公司战略规划,到2027年,公司产能将达到160亿平方米,位居全球行业领先地位。",
