    "company_profile": "    上海仙工智能科技股份有限公司(SEERRobotics)成立于2020年,是一家全球领先的平台型具身智能机器人公司,拥有全球最丰富的机器人产品,全球智能机器人控制器市占率第一,主营业务包括控制器、移动机器人(AMR)、具身智能机器人。公司创始团队毕业于浙江大学,曾三度获得RoboCup机器人足球比赛世界冠军,在机器人控制与智能系统领域拥有深厚的技术积累。仙工智能总部位于上海,全球化布局,在香港、德国、日本等地设有子公司,已获得普洛斯隐山资本、华创资本、科沃斯、IDG资本、赛富资本等多家知名机构投资。围绕“加速开放多元的智能文明,让智能机器人没有门槛”的使命,仙工智能以被誉为“机器人大脑”的控制系统为技术核心,已向全球客户提供1000+种智能机器人解决方案,拥有目前全球最丰富的智能机器人选型库,并构建了全球首家实现规模化落地的智能机器人开放平台。目前,仙工智能已服务2100+家全球客户,包括特斯拉、大众一汽、比亚迪、富士康、施耐德、西门子、卡特彼勒、联影医疗等国内外知名企业,业务覆盖汽车、3C、自动化设备、新能源、半导体、工程机械、生物医药等20+行业,产品与服务遍及70+个国家和地区。在持续的技术创新与产业实践中,仙工智能荣获国家级专精特新“重点小巨人”企业、国家工业机器人行业规范企业、上海市创新型企业总部、上海市科技小巨人企业、上海市智能机器人标杆企业、“人形机器人最强大脑”等荣誉。",
