    "company_profile": "    蓝思科技股份有限公司是以科技创新为核心、智能智造为驱动,业内领先的智能终端全产业链一站式精密制造解决方案提供商。1993年成立于深圳(公司前身),2006年总部落户湖南长沙,2015年在深交所创业板上市。2025年在香港交易所上市,实现“A+H”双资本平台的战略布局。公司在新材料应用领域持续突破,率先将玻璃、蓝宝石、陶瓷等材料引入消费电子行业,凭借对玻璃、金属、陶瓷、塑胶、皮革、硅胶、玻纤、碳纤、化纤等十余种材料的深度技术积累,并依托强大的平台化能力,公司实现了从原材料生产、功能模块贴合到整机组装的垂直整合能力,并与全球头部消费电子及智能汽车品牌建立了长期战略合作。蓝思科技通过“新材料、新技术、新装备、新领域”战略,持续不断拓展新领域,业务覆盖消费电子、智能汽车、人形机器人、AI眼镜/XR头显、AI服务器、商业航天、智慧零售设备等新兴领域,形成多场景协同发展的业务布局。在湖南、广东、江苏、越南和泰国等地区和国家拥有12大研发生产基地。",
