    "employees": "479",
    "website": "www.kalugaqueen.com",
    "company_profile": "    杭州千岛湖鲟龙科技股份有限公司是一家集繁育、养殖、加工、营销及文化推广于一体的股份制企业,借助于千岛湖优质水资源,养育水中“活化石”--鲟鱼,加工奢华盛宴美食--鱼子酱,生产高品质鲟鱼肉产品,推广鲟鱼美食文化,创造安全,营养,美味,时尚的生活体验。旗下鱼子酱品牌一卡露伽,甄选优质鲟鱼卵,经轻微盐渍后保留其醇厚清香,当鱼子酱在口中粒粒碰撞,爆裂的口感撩动起舌尖前所未有的惊叹,尊贵品位生活此刻尽享。鲟鱼肉及鱼副产品系列——千岛寻龙,则是现代科技与绿色低碳养殖模式的结合,孕育鲜嫩肥美、口味纯正的鲜美鱼肉,将名贵鲟鱼开发为非凡美味鲟龙科技秉持”质量为本\"的经营理念,以“铸民族品牌,做百年老店”为经营目标,用匠心工艺与潮流美味,为中国的饮食界注入与众不同的美食奢享体验。鲟龙科技开启了国内鲟鱼及鱼子酱产业人工养殖的先河,同时建立起一套全新的行业标准。公司坚持可持续发展理念,致力于与自然和谐发展,为此打造出环保网箱生态系统,以充分的水交换和丰富的溶氧为鲟鱼提供接近野生的生长环境。作为建立起完备产业链的市场破局者,鲟龙科技拥有大规模的现代化加工中心,秉承俄罗斯和伊朗鱼子酱传统手工工艺精髓,融合现代加工技术,在低温环境下,短时间内快速完成多道纯手工工序。加工流程严格按照HACCP管理体系操作,符合严格的国际卫生标准,从源头上保证了鱼子酱的优良品质。鲟龙科技产品采用全程冷链运输,卡露伽鱼子酱会搭乘航班直送至世界各地的餐桌上,争分夺秒锁住每克新鲜。鲟龙科技旗下高端品牌卡露伽已成功打进多个国家和地区,是多家巴黎和纽约米其林三星餐厅的甄选食材,是德国汉莎航空头等舱、国泰航空、新加坡航空的荣耀尊享,亦是美国奥斯卡晚宴、杭州G20峰会晚宴的高级点缀,以及伦敦Harrods百货和Fortum&Masion百货的首选千岛寻龙则与国内火锅餐饮明星品牌海底捞达成深度合作,未来将为更多的美食爱好者奉上风味独特的臻选鲟鱼肉美食。“这一克拥有,这一刻品位”,卡露伽传承古老技艺,沿袭拳拳匠心,打造当代新贵的盛宴,释放返璞归真的妙谛,用一克鱼子酱,换取人生的一刻高光!",
