    "website": "www.befar.com",
    "company_profile": "    滨化集团股份有限公司始建于1968年,1970年投产,现已成为主业突出、产业链完整的综合型化工企业集团,拥有氯碱、石化、新材料、特种化学品、合成生物和海外六大发展板块。产品固体烧碱、三氯乙烯、油系针状焦、纤维级聚苯硫醚市场占有率全国第一,烧碱、环氧丙烷上榜“好品山东”高端化工品牌,产品远销全球100多个国家和地区。集团核心企业滨化集团股份有限公司(简称滨化股份,SH601678)于2010年2月在上交所成功挂牌上市。公司现为中国民营企业500强(第302位)、中国制造业企业500强(第294位)、山东省重点产业链链主企业。荣获全国五一劳动奖状、全国和谐劳动关系创建示范企业、全国最具社会责任企业、全国模范职工之家、山东慈善奖、山东社会责任企业等荣誉称号,连续十一年获评全国重点用能行业产品能效“领跑者”标杆企业。综合全球化工发展大势、中国化工探索实践和滨州面临的重大机遇,滨化集团开创性地规划了面向未来的“北鲲计划”。以“新能源+化工”耦合为发展路径,构建战略科技力量体系,致力在滨州北部建设国家级新能源化工产业基地。滨化始终将科创作为决胜未来的核心竞争力,构建了以本部战略创新研究院为主体,链接多个异地实验室的科创联盟体系。当前,与山东大学联合共建“中国科技与产业整合研究中心”,致力成为国家战略与产业变革的智慧引擎,推动研究成果向政策制定、技术转化与资本赋能高效落地;设立“北鲲青年科学家奖”,每年出资2000余万元,全力打造“北鲲一院士创新港”“北海大型化工新材料中试基地”旨在构建科技赋能产业发展的生态体系。当前滨化制定了全新的“12345”战略定位和发展逻辑,擘画了“科技滨化、数字滨化、国际滨化、幸福滨化”的恢弘愿景。滨化坚持价值创造与人文精神并重,厚植蝶变求新、敏锐洞察的变革文化,在生态构建、科技创新、绿色转型、国际拓展和社会责任等方面持续发力,以更加开放的视野和胸怀与时代共行。穿云九重,驭风万里。面向未来,滨化集团将谋定战略布局、坚定发展信心,以国际化视野谋划开放合作,以科技创新驱动跨越发展,致力于成为绿色化工、低碳转型的探索者和实践者,为社会、客户、股东、员工创造最大价值,为推动全球化工行业发展作出更大贡献!",
