    "chairman": "敬玥",
    "employees": "327",
    "website": "www.jxswzp.cn",
    "company_profile": "    江西生物制品研究所股份有限公司历史可追溯至1969年,前身为卫生部上海生物制品研究所江西分所,历经五十余年发展积淀,已形成深厚的生物制药技术底蕴与产业基础。2002年完成有限责任公司改制,2017年12月实施股份制改造,在几代科研与经营团队接续奋斗下,现已发展成为本国抗毒素及免疫血清类生物制品领域的国家高新技术领军企业。公司以国家生物医药产业发展战略为指引,构建起覆盖全国的\"三基地二中心\"战略布局体系,下辖八家全资子公司,形成完整的生物制品产业生态链。在江西建有专业化人用医药产品基地,专注抗毒素及免疫血清类产品研发制造;于甘肃省设立马匹饲养及免疫马血浆采集基地,从源头保障核心原料供应;在内蒙古建设符合GMP标准的兽用医药产品基地,有效填补行业空白;在深圳市设立前沿药品研发中心,整合产学研医用于一体,推进生物技术创新;在海南省搭建医药研发技术服务平台,实现全球优质资源高效整合。公司坚持全产业链垂直整合发展模式,建立起涵盖原料采集、研发生产、终端交付的全流程闭环管理体系。依托严苛的质量管控标准和数字化监控系统,公司实现核心原料自主可控、生产成本优化管理,产品质量稳定性达到行业领先水平。凭借完整的产业链协同优势,公司持续为全球客户提供安全、高效、稳定的生物制品,在国际市场竞争中展现出强大的产业竞争力与可持续发展能力。公司主营业务涵盖生物制品研发生产、实验用动物饲养及生物技术推广服务、药品检测和检验、药品研发、药物安全评价及相关技术服务,核心产品破伤风抗毒素(免疫球蛋白)先后荣获“第七届亚细安中医药学术大会金奖、江西省优秀新产品”等多项荣誉,获评“江西省赣出精品、江西名牌”称号。公司生产销售能力突出,产品已出口至30余个国家和地区,累计服务全球超十亿用户,市场影响力和品牌美誉度持续提升。公司高度重视科技创新与人才培养,建有“省级企业技术中心、江西省生物免疫抗体药物研发中心”等多个省级以上科研平台,并设立“江西省博士后创新实践基地、省市级海智计划工作站及市专家工作站”。通过实施人才强企战略,公司汇聚了一批高素质管理、技术及研发人才,同时配备专业化、数字化、智能化的先进生产研发设备,形成强大的科研创新能力和科技成果转化能力。公司在发展过程中屡获殊荣,先后被认定为“国家高新技术企业”,荣获“全国讲比工作先进集体、江西省专精特新企业、江西省专业化小巨人企业”等荣誉称号。同时,公司积极履行社会责任,多次获评“江西省优秀企业、省级民营科技企业、省先进基层党组织、江西省工人先锋号”等称号,连续多年被评为“吉安市十佳民营科技企业、文明单位、纳税大户”。面向未来,公司将始终秉持\"为全球百姓做优质药品\"的使命担当,以打造\"全球血清基地\"为战略目标,持续引进国际先进技术,推进工艺革新与产品升级。通过实施重大项目带动战略,加快资本市场布局,进一步提升企业核心竞争力和国际影响力,为推动本国生物制药产业高质量发展、保障人民群众生命健康作出更大贡献。",
