    "company_profile": "    苏州瑞博生物技术股份有限公司专注于RNA干扰(RNAi)技术开发及小核酸药物产业化,是全球较早布局该领域的开拓者之一,于2026年1月成功在香港交易所主板挂牌上市(股票代码:06938.HK)。公司建立了自主可控、全技术链整合的小核酸药物研发平台,构建了全球一体化的小核酸药物开发体系,布局覆盖心血管、代谢、肾病及肝病等慢病领域的多元化siRNA管线。公司依托国际化研发平台,实现小核酸药物全周期技术覆盖,包括药物递送、化学修饰、多靶点药物研发、模型引导的药物开发及药学开发生产。其中,自主研发的肝靶向递送技术RiboGalSTARTM,推动多款产品进入临床II期,其有效性和安全性得到很好的临床验证。瑞博生物与全球领先MNC达成RNAi领域战略合作,创中国生物科技企业平台级合作先例,标志着跨国药企对公司研发平台与科研实力的高度认可。基于前瞻性的全球化战略布局,公司已经在中国北京和苏州以及欧洲建立多个研发中心。",
