    "company_profile": "    潮州三环(集团)股份有限公司成立于1970年,2014年在深交所上市(股票简称:三环集团,股票代码:300408),在潮州、深圳、成都、德阳、南充、苏州、武汉、香港、德国、泰国等地均设有公司,是一家专注于先进材料研发、生产及销售的综合性高新技术企业。半个世纪以来,公司秉承“‘材料+’构筑美好生活”的愿景,聚焦“材料”基因,以“材料+结构+功能”为发展方向,产品覆盖通信、电子、新能源、半导体、移动智能终端等众多应用领域。其中,光通信用陶瓷插芯、片式电阻用氧化铝陶瓷基板、半导体陶瓷封装基座等产品产销量均居全球前列,多项产品先后荣获国家优质产品金奖。公司被认定为国家高新技术企业、国家技术创新示范企业、国家企业技术中心、中国制造业单项冠军示范企业,连续多年入选中国电子元件百强企业。三环集团始终践行“诚信勤勉、科技创新、成就人才、开放融合、行稳致远、追求卓越”的企业价值观,致力于为客户需求提供解决方案,为员工成长搭建发展平台,为股东投资创造增值回报,为社会发展贡献企业价值。公司以人才和创新为发展核心,坚持“倾心引才、精心用才、悉心育才、真心爱才、匠心成才”的人才理念,大力引进和培养高素质人才,不断推动自主创新和转型升级。三环集团拥有以博士、硕士为主组成的技术研发团队,同时聘请多名两院院士及多位学科专家组成科学技术专家委员会,不断开展新材料、新产品、新技术的研究与创新,承担并完成多个国家、省级重点科研项目。公司坚持科学导向的创新理念与实事求是的思想原则,着眼于前沿技术开发,聚焦重点任务和关键环节,不断推进企业的高质量发展。未来,三环集团将坚持永不停步的创新动力,开拓可持续发展的产品方向,完善能自我修正的管理机制,建立有凝聚力的企业文化,竭力打造集科技研发、高端制造、技术支持、人才聚集、市场服务等于一体的综合性产业基地,用技术创新引领高质量发展,用“材料+”构筑美好生活。",
