    "website": "www.shuangdeng.com.cn",
    "company_profile": "    双登集团股份有限公司,“大数据时代绿色储能集成服务供应商”,以前瞻的能源科技,与全球客户共享绿色地球。\n    公司积极探索,发现不断增长的能源新世界——在通信,双登拥有全系列能源存储解决方案,提供坚实的绿色能源保障;在电力,双登正在成为构建未来智能电网的核心中枢;在动力,新清洁、高效的动力能源,为社会发展提供无限助力;在回收,双登率先构建循环产业链,让能源变得可循环,可再生,减少资源损失,还原健康地球。\n    公司追求极致,塑造具有强劲可持续发展力的企业——双登是业内“国家环境友好企业”,也是“国家重点高新技术产业集团”、“中国电子信息百强企业”、“全球新能源企业500强”等荣誉获得者。\n    公司汇聚全球行业专家,联合科研院所,与客户协同,研发智慧能源——建立与中科院合作成立的先进能源发展研究中心、院士工作站、博士后科研工作站、国家认定企业技术中心,承担国家863等科研项目并研发世界前瞻性高端新能源项目。\n    公司利用互联网平台、大数据云存储,服务全球客户,取得了全球诸多区域市场的进网认证,销往五大洲的多个国家和地区。\n    存储大爱和绿色能源,公司坚定推进绿色低碳事业,忠贞不渝的实践“新能源、循环性、高科技”理念的信仰指引,注重从设计开发、绿色采购、体系管理、循环回收、节能减排五大环节重点管理,为行业创造绿色模式,为人类营造绿色生活,为地球存储绿色未来。能动创新,大德同心。",
