    "company_profile": "    宁波均胜电子股份有限公司(简称“均胜电子”,600699.SH/00699.HK)是一家全球领先的智能汽车科技解决方案提供商,主要致力于智能座舱、智能网联、智能驾驶、新能源管理和汽车安全系统等的研发、制造与服务。均胜电子总部位处中国浙江省宁波市,公司业务架构分为智能汽车科技研究院、新能源研究院、汽车电子事业部与汽车安全事业部,并在全球设有超过25个研发中心和超过60个生产基地,覆盖亚洲、欧洲和北美等主要汽车市场。成立于2004年的均胜电子从汽车功能件为主业的零部件起步,2011年至今,公司先后收购了德国PREH、德国QUIN、美国KSS以及日本高田资产(PSAN业务除外)等。通过企业创新升级和多次国际并购,公司实现全球化和转型升级的战略目标。公司现有产品涵盖包括座舱域、智驾域、网联域、动力域和车身域等主要汽车域。凭靠先进的创新设计、生产制造、品质管理及优秀服务,均胜电子成为宝马、奔驰、奥迪、大众、通用、福特、本田和丰田等全球汽车制造商的长期合作伙伴,并屡获保时捷、大众、通用等汽车制造商优秀供应商奖。",
