    "company_profile": "    南京英派药业股份有限公司成立于2009年,是一家处于商业化阶段的生物技术公司,致力于在全球范围内推进基于合成致死机制的精准抗癌疗法,打造创新疗法,以满足癌症患者未被满足的医疗需求。\r\n公司通过自主研发建立了最全面、最先进的合成致死产品组合之一,也是全球仅有的三家同时拥有商业化阶段的PARP1/2抑制剂和临床阶段新一代PARP1选择性抑制剂的公司之一。\r\n核心产品塞纳帕利(IMP4297)于2025年1月获批用于中国卵巢癌 “全人群” 一线维持治疗后正式启动商业化,并自2026年1月1日起纳入国家医保药品目录。塞纳帕利在中国卵巢癌 “全人群” 一线维持治疗的 PARP1/2 抑制剂中(非头对头研究)中实现了最有利的PFS结果,为该类药物树立了新标杆。\r\n公司已搭建双载荷抗体偶联药物(ADC)平台及蛋白降解剂平台,研发管线覆盖PARP1/2、PARP1、ATR、WEE1、PKMYT1/WEE1、DHX9、ATM、USP1及CHK1/2等关键合成致死靶点的小分子抑制剂,以及CEACAM5双载荷抗体偶联药物和KAT6A选择性蛋白降解剂。",
