    "company_profile": "    奇瑞汽车股份有限公司是一家乘用车公司,总部位于中国芜湖。本公司设计、开发、制造和销售多样化且不断扩展的乘用车产品组合,包括燃油车和新能源汽车,满足国内外市场用户的不同及不断变化的需求和喜好。\r\n自1997 年成立以来,本公司致力于引领行业创新和深耕国际市场,为全球用户提供高品质的乘用车。根据弗若斯特沙利文的资料,于2024 年,按销量计,本公司为中国第二大自主品牌乘用车公司,亦为全球第十一大乘用车公司,本公司的乘用车销量较2023 年增长49.4%,增速位居全球前二十大乘用车公司之首。全球前二十大乘用车公司中,本公司是唯一一家新能源汽车销量、燃油车销量、中国市场销量及海外市场销量与2023 年相比增幅均超过25.0%的公司。\r\n本公司的五大品牌为奇瑞、捷途、星途、iCAR 和智界,每个主要品牌都有独特的定位、出行风格和审美认知,满足不同客户需求,并覆盖各具显着增长潜力的细分赛道。\r\n技术实力是本公司汽车开发的核心,亦是本公司迄今为止取得成功的关键。多年来,本公司建立了全方位技术堆栈,包括鲲鹏动力、火星架构、雄狮智舱及辅助驾驶系统等。\r\n本公司致力于成为创新驱动、全球信赖的智能出行生态参与者。本公司秉持「In somewhere, For somewhere」理念,致力于为全球用户提供绿色产品,为社会贡献持续发展的价值。",
