    "company_profile": "    深圳市沃尔核材股份有限公司(简称:沃尔核材,股票代码:002130)是国家重点支持发展的高新技术企业,专业从事高分子辐射改性新材料研发、制造和销售。成立于1998年6月,拥有20多年的热缩材料研发和生产经验。沃尔核材产品包括:热缩套管、热缩母排、热缩电缆附件、冷缩电缆附件、电缆分支箱、环网柜、高低压开关柜、WQFB全绝缘封闭母线、环保高温硅胶电线、耐高温聚四氟乙烯套管、导体连接管、热缩复合双壁管、硅橡胶管、聚四氟乙烯套管、民用防滑花纹管、无卤环保PE交联电线等2500多种产品,广泛应用于电子、电力、冶金、石化、汽车、高铁、煤矿及航天航空等领域,销售分公司遍及全国40多个大中城市,产品远销欧美、东南亚等多个国家和地区,其质量稳定、性能可靠,已形成“沃尔核材”品牌效应。沃尔核材先后获得了“中国驰名商标”、“国家企业技术中心”、“民用核安全设备设计许可证”、“中国自主创新能力行业十强”、“深圳市长质量奖提名奖”、“深圳市自主创新百强中小企业”、“最具影响力的深圳知名品牌”、“深圳市首届AAA进出口诚信企业”、“科技创新大奖”、“深圳市企业新纪录”金奖、“深圳市诚信企业”、“坪山区质量奖”连续多年获得“深圳市科技进步奖”等荣誉称号。沃尔核材以“诚信·共赢”的经营思想,吸纳和培训优秀人才。为各位人才提供了广阔的舞台。倡导科技创新引领行业发展,诚信经营推动社会进步,勇于承担社会责任,奉献爱心。沃尔核材将秉承“企业成功、员工幸福、回报社会”企业使命,凭借品牌、技术、市场、服务等强大实力,恪守“艰苦奋斗、务实高效、合作共赢”核心价值观,全力打造一个行业地位领先、竞争优势显著、企业特色鲜明、社会尊重、员工自豪的优质企业。",
